class Solution:
    def minWindow(self, s: str, t: str) -> str:
        need = Counter(t)               # 每种字符还差几个
        missing = len(t)                # 一共还差几个
        l = start = 0
        size = float("inf")
        for r, ch in enumerate(s):
            if need[ch] > 0:
                missing -= 1
            need[ch] -= 1
            while missing == 0:         # 窗口合格，尝试收缩
                if r - l + 1 < size:
                    start, size = l, r - l + 1
                need[s[l]] += 1
                if need[s[l]] > 0:
                    missing += 1
                l += 1
        return "" if size == float("inf") else s[start:start + size]

