var minWindow = function(s, t) {
    const need = new Map();                         // 每种字符还差几个
    for (const c of t) need.set(c, (need.get(c) || 0) + 1);
    let missing = t.length;                         // 一共还差几个
    let l = 0, start = 0;
    let size = Infinity;
    for (let r = 0; r < s.length; r++) {
        const ch = s[r];
        if ((need.get(ch) || 0) > 0) {
            missing--;
        }
        need.set(ch, (need.get(ch) || 0) - 1);
        while (missing === 0) {                     // 窗口合格，尝试收缩
            if (r - l + 1 < size) {
                start = l;
                size = r - l + 1;
            }
            need.set(s[l], need.get(s[l]) + 1);
            if (need.get(s[l]) > 0) {
                missing++;
            }
            l++;
